markers=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==6]
from collections import defaultdict
writes=defaultdict(list)
for r,c in markers:
 for dr,val in [(-1,8),(0,3),(1,0)]:
  rr=r+dr
  if 0<=rr<len(g): writes[(rr,c)].append((val,(r,c)))
conf={p:v for p,v in writes.items() if len({x[0] for x in v})>1}
print('markers',len(markers),'conflicting writes',conf)
out=[row[:] for row in g]
for (r,c),vals in writes.items():
 # With non-conflicting motif propagation, all expected assignments agree.
 assert len({x[0] for x in vals})==1, (r,c,vals)
 out[r][c]=vals[0][0]
print(out)
